\noindent\textit{Poznámka: níže uvedené body jsou obecná doporučení (``general background knowledge'') a měly by být ověřeny lokálním pilotem před plošným nasazením.}

\medskip

\begin{itemize}
  \item Požadavky před nasazením:
    \begin{itemize}
      \item jasně definovaná rubrika pro krátké odpovědi (co se hodnotí, jaké jsou stupně kvality);
      \item anonymizovaná testovací sada reálných studentských odpovědí pro ladění a validaci;
      \item zajištění souhlasu a ochrany osobních údajů pro zpracování studentských dat;
      \item technické rozhraní pro export/import odpovědí a protokolování rozhodnutí modelu.
    \end{itemize}

  \item Návrh metrik kvality (příklady):
    \begin{itemize}
      \item shoda s lidským hodnocením (míra, jak často automatické skóre odpovídá ručnímu);
      \item konzistence (stabilita skóre při opakovaných spuštěních nebo malých úpravě textu);
      \item užitnost pro učitele (zrychlení práce, snížení administrativy) a spokojenost studentů.
    \end{itemize}

  \item Základní implementační postup:
    \begin{enumerate}
      \item definujte cíle hodnocení a připravte rubriku;
      \item sestavte validační sadu s ručně ohodnocenými příklady;
      \item vyberte nástroj nebo model a nastavte předzpracování (tokenizace, normalizace);
      \item spusťte pilot: automatické hodnocení + lidská kontrola vybraného vzorku;
      \item vyhodnoťte metriky shody a identifikujte systematické odchylky; upravte rubriku nebo model;
      \item dokumentujte pravidla a výsledky pro audit a komunikujte je studentům.
    \end{enumerate}

  \item Validace proti ručnímu hodnocení:
    \begin{itemize}
      \item ověřte automatické skóry na náhodném nebo stratifikovaném vzorku z různých úrovní obtížnosti;
      \item porovnejte distribuce skóre a analyzujte případy, kde se systém a hodnotitel liší (chyby podhodnocení/nadhodnocení);
      \item při zjištění významných rozdílů zaveďte kombinovaný workflow (automatické skóre slouží jako návrh, finální rozhodnutí dělá člověk).
    \end{itemize}

  \item Praktické tipy pro pilot:
    \begin{itemize}
      \item začněte úzkým obsahem (konkrétní typ otázek), než systém rozšíříte;
      \item informujte studenty o použití automatizace a možnostech oprav/námitky;
      \item uchovávejte záznamy rozhodnutí modelu a oprav učitelů pro pozdější audit a zlepšování.
    \end{itemize}
\end{itemize}
